@deva[त्क] @[t-ka], @deva[त्क्र] @[t-k-ra], @deva[त्त] @[t-ta], @deva[त्त्य] @[t-t-ya], @deva[त्त्र] @[t-t-ra], @deva[त्त्व] @[t-t-va], @deva[त्थ] @[t-tha], @deva[त्न] @[t-na], @deva[त्न्य] @[t-n-ya], @deva[त्प] @[t-pa], @deva[त्म] @[t-ma], @deva[त्म्य] @[t-m-ya], @deva[त्य] @[t-ya], @deva[त्र] or @deva[त्र] @[t-ra], @deva[त्र्य] or @deva[त्र्य] @[t-r-ya], @deva[त्व] @[t-va], @deva[त्स] @[t-sa], @deva[त्स्न] @[t-s-na], @deva[त्स्न्य] @[t-s-n-ya], @deva[त्स्य] @[t-s-ya].

